pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(nonOwner != c.owner());

        bool success;
        vm.prank(nonOwner);
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(!success);
    }
}
